/* A grade do mural (pronta): 3 colunas e 4 linhas */
.mural {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(4, 110px);
  gap: 12px;
  max-width: 720px;
  margin: 0 auto;
}

.mural article {
  background-color: #fff;
  border: 2px solid #1b1e24;
  border-radius: 10px;
  padding: 10px;
  overflow: hidden;
}

.mural h2 {
  font-size: 16px;
  margin: 0 0 6px;
}

.mural p {
  font-size: 14px;
  margin: 0;
}

.mural .destaque {
  background-color: #ffd23f;
}

.mural .destaque h2 {
  font-size: 24px;
}

.mural .aviso {
  background-color: #90caf9;
  text-align: center;
}

